<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add_vhost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mall</span></span>
